package com.hozefa.threepattipro.nativeapp;

import android.app.Activity;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.function.IntConsumer;

/** Native analytics views. This renderer has no Firebase gateway or write capability. */
final class AdvancedAnalyticsPage {
    interface Host {void choose(String title,String[] labels,IntConsumer action);void changed();void profile(String id);void round(Map<String,Object> round);void share();void draw(View view,java.util.function.Consumer<Float> frame);void tap(View view);}
    static final String[] SECTIONS={"Overview","Player comparison","Role performance","Bid analysis","Partnership chemistry","Form & consistency","Comeback & lead tracker","Session comparison","Round impact","Personal records","Auto insights"};
    static final class State {
        int section,window=10,limit=20;String player="",rival="",scope="all",sessionA="",sessionB="";
        void save(Bundle b){b.putInt("analysis_section",section);b.putInt("analysis_window",window);b.putInt("analysis_limit",limit);b.putString("analysis_player",player);b.putString("analysis_rival",rival);b.putString("analysis_scope",scope);b.putString("analysis_session_a",sessionA);b.putString("analysis_session_b",sessionB);}
        void restore(Bundle b){section=Math.max(0,Math.min(SECTIONS.length-1,b.getInt("analysis_section",0)));window=b.getInt("analysis_window",10);if(window!=5&&window!=10&&window!=20)window=10;limit=Math.max(20,b.getInt("analysis_limit",20));player=b.getString("analysis_player","");rival=b.getString("analysis_rival","");scope=b.getString("analysis_scope","all");sessionA=b.getString("analysis_session_a","");sessionB=b.getString("analysis_session_b","");}
    }
    private final Activity a;private final LinearLayout root;private final State state;private final AdvancedAnalytics.Report report;private final List<Map<String,Object>> metadata;private final Host host;
    private final int panel,gold,green,red,blue;private static final int WHITE=0xffffffff,MUTED=0xffa4a7ae,BORDER=0xff35343a;
    AdvancedAnalyticsPage(Activity a,LinearLayout root,State state,AdvancedAnalytics.Report report,List<Map<String,Object>> metadata,int panel,int gold,int green,int red,int blue,Host host){this.a=a;this.root=root;this.state=state;this.report=report;this.metadata=metadata;this.panel=panel;this.gold=gold;this.green=green;this.red=red;this.blue=blue;this.host=host;}
    void render(){
        button(root,"View · "+SECTIONS[state.section],()->host.choose("Analytics view",SECTIONS,i->{state.section=i;state.limit=20;host.changed();}));
        button(root,"Round scope · "+scopeName(),this::pickScope);
        note(root,"Saved table rounds only · Practice and settlement adjustments are excluded. All views follow the date and session filters above.");
        if(report.rounds.isEmpty()){cardMessage("No rounds in this scope","Try All Time / All sessions, or save a table round first. No result is inferred from an empty history.");return;}
        if(!report.names.containsKey(state.player))state.player=firstPlayer("");
        if(!report.names.containsKey(state.rival)||state.player.equals(state.rival))state.rival=firstPlayer(state.player);
        if(state.section!=0){button(root,"Player · "+name(state.player),()->pickPlayer(false));}
        switch(state.section){case 0:overview();break;case 1:comparison();break;case 2:roles();break;case 3:bids();break;case 4:pairs();break;case 5:form();break;case 6:leaders();break;case 7:sessions();break;case 8:impacts();break;case 9:records();break;case 10:insights();break;default:break;}
    }
    private int dp(float n){return Math.round(a.getResources().getDisplayMetrics().density*n);}
    private TextView text(String value,int size,int color,boolean bold){TextView t=new TextView(a);t.setText(value);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
    private void gap(LinearLayout parent,int n){View v=new View(a);parent.addView(v,new LinearLayout.LayoutParams(1,dp(n)));}
    private LinearLayout card(String title){LinearLayout c=new LinearLayout(a);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(16),dp(16),dp(16),dp(16));GradientDrawable bg=new GradientDrawable();bg.setColor(panel);bg.setCornerRadius(dp(18));bg.setStroke(dp(1),BORDER);c.setBackground(bg);if(!title.isEmpty()){c.addView(text(title,18,WHITE,true));gap(c,12);}root.addView(c,new LinearLayout.LayoutParams(-1,-2));gap(root,12);return c;}
    private void note(LinearLayout c,String value){TextView t=text(value,13,MUTED,false);t.setLineSpacing(dp(2),1);c.addView(t);gap(c,10);}
    private TextView button(LinearLayout c,String label,Runnable action){TextView b=text(label,15,gold,true);b.setMinHeight(dp(48));b.setGravity(Gravity.CENTER_VERTICAL);b.setPadding(dp(14),dp(10),dp(14),dp(10));GradientDrawable bg=new GradientDrawable();bg.setColor(panel);bg.setCornerRadius(dp(12));bg.setStroke(dp(1),BORDER);b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf((gold&0x00ffffff)|0x33000000),bg,null));b.setOnClickListener(v->{host.tap(v);action.run();});b.setFocusable(true);c.addView(b,new LinearLayout.LayoutParams(-1,-2));gap(c,8);return b;}
    private TextView metric(LinearLayout c,String label,String value,int color){LinearLayout row=new LinearLayout(a);row.setOrientation(LinearLayout.HORIZONTAL);row.setPadding(0,dp(5),0,dp(5));TextView l=text(label,14,MUTED,false),r=text(value,15,color,true);r.setGravity(Gravity.END);row.addView(l,new LinearLayout.LayoutParams(0,-2,1.1f));row.addView(r,new LinearLayout.LayoutParams(0,-2,1));c.addView(row);return r;}
    private String name(String id){return report.names.getOrDefault(id,"No second player");}
    private String signed(long n){return (n>0?"+":"")+n;}
    private String dec(double n){return String.format(Locale.ROOT,"%.1f",n);}
    private String rate(AdvancedAnalytics.Stats s){return s.decided()==0?"—":dec(s.rate())+"%";}
    private void sample(LinearLayout c,AdvancedAnalytics.Stats s){note(c,s.played==0?"No played rounds for this player in this scope.":s.played<10||s.decided()<10?"Limited data · "+s.played+" played / "+s.decided()+" decided rounds. Small samples can fluctuate.":s.played+" played / "+s.decided()+" decided rounds. Observed results, not a prediction.");if(s.unknown>0)note(c,s.unknown+" unknown results excluded from win rates and break streaks.");}
    private void summary(LinearLayout c,AdvancedAnalytics.Stats s){TextView score=metric(c,"Total points",signed(s.points),s.points>=0?green:red);
        if(s.points>=Integer.MIN_VALUE&&s.points<=Integer.MAX_VALUE)for(String id:report.players.keySet())if(report.players.get(id)==s)score.setTag(new MotionEngine.Anchor("analytics-score:"+id+":"+state.scope+":"+state.section,(int)s.points,s.points>0));
        metric(c,"Points / played round",dec(s.average),gold);metric(c,"Wins / losses",s.wins+" / "+s.losses,WHITE);metric(c,"Win rate",rate(s),blue);sample(c,s);}
    private void cardMessage(String title,String message){note(card(title),message);}
    private String firstPlayer(String exclude){for(String id:report.names.keySet())if(!id.equals(exclude)&&report.players.get(id).played>0)return id;for(String id:report.names.keySet())if(!id.equals(exclude))return id;return "";}
    private void pickPlayer(boolean rival){List<String> ids=new ArrayList<>();for(String id:report.names.keySet())if(!id.equals(rival?state.player:state.rival)||!rival)ids.add(id);String[] labels=new String[ids.size()];for(int i=0;i<labels.length;i++)labels[i]=name(ids.get(i));host.choose(rival?"Compare with":"Choose player",labels,i->{if(rival)state.rival=ids.get(i);else{state.player=ids.get(i);if(state.player.equals(state.rival))state.rival=firstPlayer(state.player);}host.changed();});}
    private String scopeName(){if("all".equals(state.scope))return "All sessions";if("current".equals(state.scope))return "Current session";if("previous".equals(state.scope))return "Previous completed session";if("unassigned".equals(state.scope))return "Unassigned rounds";String id=state.scope.startsWith("session:")?state.scope.substring(8):"";for(Map<String,Object> s:metadata)if(id.equals(AdvancedAnalytics.text(s,"id")))return AdvancedAnalytics.text(s,"sessionName");return "Selected session";}
    private void pickScope(){List<String> values=new ArrayList<>(Arrays.asList("all","current","previous","unassigned")),labels=new ArrayList<>(Arrays.asList("All sessions","Current session","Previous completed session","Unassigned rounds"));for(Map<String,Object> s:metadata){String id=AdvancedAnalytics.text(s,"id");if(id.isEmpty())continue;values.add("session:"+id);labels.add(AdvancedAnalytics.text(s,"sessionName")+" · "+date(s.get("startTime")));}host.choose("Round scope",labels.toArray(new String[0]),i->{state.scope=values.get(i);state.limit=20;host.changed();});}
    private String date(Object value){long t=AdvancedAnalytics.time(value);return t==Long.MIN_VALUE?"Undated":DateTimeFormatter.ofPattern("dd MMM yyyy, HH:mm").withZone(ZoneId.systemDefault()).format(Instant.ofEpochMilli(t));}
    private List<String> ranking(){List<String> ids=new ArrayList<>(report.names.keySet());ids.removeIf(id->report.players.get(id).played==0);ids.sort((x,y)->{int c=Long.compare(report.players.get(y).points,report.players.get(x).points);return c==0?x.compareTo(y):c;});return ids;}
    private void more(int total){if(total>state.limit)button(root,"Show more · "+state.limit+" of "+total,()->{state.limit+=20;host.changed();});}
    private void overview(){LinearLayout c=card("Selected table");metric(c,"Saved rounds",String.valueOf(report.rounds.size()),WHITE);metric(c,"Players with rounds",String.valueOf(ranking().size()),gold);metric(c,"Leader changes",String.valueOf(report.leaderChanges),blue);
        long bids=0,highest=0;int count=0,wins=0,known=0;for(Map<String,Object> r:report.rounds){long bid=AdvancedAnalytics.number(r.get("bid"));if(bid>0){bids+=bid;highest=Math.max(highest,bid);count++;}int result=AdvancedAnalytics.result(r,AdvancedAnalytics.text(r,"hukumId"));if(result!=0){known++;if(result>0)wins++;}}
        metric(c,"Average / highest bid",(count==0?"—":dec((double)bids/count))+" / "+(count==0?"—":String.valueOf(highest)),gold);metric(c,"Hukum win rate",known==0?"—":dec(100d*wins/known)+"% · "+known+" decided",green);note(c,"Choose an analytics view above for comparisons, roles, bids, partnerships, form, leads, sessions, round impact, records or insights.");
        root.addView(text("PLAYER PERFORMANCE",14,gold,true));gap(root,12);List<String> ranked=ranking();for(int i=0;i<Math.min(state.limit,ranked.size());i++){String id=ranked.get(i);LinearLayout p=card(name(id));p.setTag(new MotionEngine.Anchor("rank:analytics:"+id+":"+state.scope));summary(p,report.players.get(id));button(p,report.rosterIds.contains(id)?"Open player profile":"View historical player records",()->{if(report.rosterIds.contains(id))host.profile(id);else{state.player=id;state.section=9;host.changed();}});}more(ranked.size());button(root,"Share this leaderboard",host::share);
    }
    private void comparison(){if(state.rival.isEmpty()){cardMessage("Player comparison","At least two players are needed to compare.");return;}button(root,"Compare with · "+name(state.rival),()->pickPlayer(true));AdvancedAnalytics.Stats x=report.players.get(state.player),y=report.players.get(state.rival);LinearLayout c=card(name(state.player)+"  vs  "+name(state.rival));metric(c,"Total points",signed(x.points)+" / "+signed(y.points),gold);metric(c,"Played rounds",x.played+" / "+y.played,WHITE);metric(c,"Average points",dec(x.average)+" / "+dec(y.average),gold);metric(c,"Win rate",rate(x)+" / "+rate(y),blue);sample(c,x);sample(c,y);note(c,"Values follow the name order above. Different round counts affect totals; compare averages as well.");
        int together=0,against=0,wins=0,decided=0;for(Map<String,Object> r:report.rounds){String a=AdvancedAnalytics.role(r,state.player),b=AdvancedAnalytics.role(r,state.rival);if(a.isEmpty()||b.isEmpty())continue;if(a.equals("Opponent")==b.equals("Opponent"))together++;else{against++;int result=AdvancedAnalytics.result(r,state.player);if(result!=0)decided++;if(result>0)wins++;}}
        metric(c,"Same side / opposing",together+" / "+against,WHITE);metric(c,"Wins against rival",wins+" / "+decided+" decided",green);chart(c,report.rounds,state.player,state.rival,"Comparison score trend");
    }
    private void roles(){for(String role:new String[]{"Hukum","Partner","Opponent"}){LinearLayout c=card(role+" performance");summary(c,report.roleStats(state.player,role));}cardMessage("How wins are counted","Hukum and Partners win when the saved Hukum result is win. Opponents win when it is loss. Zero points alone do not mean a loss.");}
    private void bids(){Map<Long,AdvancedAnalytics.Stats> bids=report.bids(state.player);cardMessage("Your Hukum bids","Only rounds where this player called Hukum are included. Gains and losses use saved point changes, not a recalculated score.");if(bids.isEmpty()){cardMessage("No Hukum bids","Choose another player or a wider date range.");return;}int count=0;for(Map.Entry<Long,AdvancedAnalytics.Stats> e:bids.entrySet()){if(count++>=state.limit)break;LinearLayout c=card(e.getKey()>0?"Bid "+e.getKey():"Unspecified bid");AdvancedAnalytics.Stats s=e.getValue();summary(c,s);metric(c,"Points gained",signed(s.gained),green);metric(c,"Points lost",s.lost==0?"0":"−"+s.lost,red);}more(bids.size());}
    private void pairs(){cardMessage("Hukum-team partnerships","Counts only rounds where both players were on the Hukum/Partner side. Opponent-side rounds are not called partnerships. Both players' point changes are combined.");List<AdvancedAnalytics.Pair> pairs=report.pairs(state.player);if(pairs.isEmpty()){cardMessage("No partnerships yet","This player has no saved Hukum-team rounds with another player in this scope.");return;}for(int i=0;i<Math.min(state.limit,pairs.size());i++){AdvancedAnalytics.Pair p=pairs.get(i);LinearLayout c=card(name(state.player)+" + "+name(p.peer));metric(c,"Rounds together",String.valueOf(p.rounds),WHITE);metric(c,"Team wins",p.wins+" / "+p.decided+" decided",green);metric(c,"Win rate",p.decided==0?"—":dec(p.rate())+"%",blue);metric(c,"Combined points",signed(p.points),gold);metric(c,"Combined / round",dec(p.average()),gold);note(c,p.decided<10?"Limited data · Fewer than 10 decided rounds together.":"Sorted by observed win rate among pairs with 10+ decided rounds first; ties use sample size.");}more(pairs.size());}
    private void windows(){LinearLayout row=new LinearLayout(a);row.setOrientation(LinearLayout.HORIZONTAL);for(int n:new int[]{5,10,20}){TextView b=text((state.window==n?"● ":"")+"Last "+n,14,state.window==n?gold:MUTED,true);b.setMinHeight(dp(48));b.setGravity(Gravity.CENTER);b.setOnClickListener(v->{host.tap(v);state.window=n;host.changed();});row.addView(b,new LinearLayout.LayoutParams(0,-2,1));}root.addView(row);gap(root,10);}
    private void form(){windows();AdvancedAnalytics.Form f=report.form(state.player,state.window);LinearLayout c=card("Recent form · Last "+state.window+" played rounds");summary(c,f.now);metric(c,"Previous window average",f.before.played==0?"—":dec(f.before.average)+" · "+f.before.played+" rounds",MUTED);note(c,f.comparable(state.window)?"Both windows contain "+state.window+" played rounds. Average change: "+dec(f.now.average-f.before.average)+" points/round.":"Partial windows · Need "+(state.window*2)+" played rounds for a complete comparison.");metric(c,"Point variability",dec(f.now.variation),blue);note(c,"Typical spread (standard deviation) of round points. Lower values mean steadier points; compare the average alongside this.");AdvancedAnalytics.Stats all=report.players.get(state.player);metric(c,"Current win / loss streak",all.currentWins+" / "+all.currentLosses,WHITE);metric(c,"Longest win / loss streak",all.longestWins+" / "+all.longestLosses,WHITE);note(c,"Streaks follow played rounds in the selected scope; absences are skipped, unknown results break the run.");chart(c,f.recent,state.player,"","Recent score trend");}
    private String leaderNames(Set<String> ids){List<String> names=new ArrayList<>();for(String id:ids)names.add(name(id));return String.join(" + ",names);}
    private void leaders(){AdvancedAnalytics.Stats s=report.players.get(state.player);LinearLayout c=card("Comeback & lead tracker");metric(c,"Largest recovered deficit",report.comeback.getOrDefault(state.player,0L)+" points",green);metric(c,"Highest lead margin",report.highestLead.getOrDefault(state.player,0L)+" points",gold);metric(c,"Table leader changes",String.valueOf(report.leaderChanges),blue);note(c,"A comeback counts a deficit later recovered to a tied or outright lead. Lead margin is over the second player. Ranking starts when each player first appears in this filtered history; tied places share competition rank.");sample(c,s);chart(c,report.rounds,state.player,"","Leaderboard score trend");List<AdvancedAnalytics.Frame> changes=new ArrayList<>();Set<String> previous=Collections.emptySet();for(AdvancedAnalytics.Frame f:report.timeline){if(!f.leaders.equals(previous)){changes.add(f);previous=f.leaders;}}Collections.reverse(changes);for(int i=0;i<Math.min(state.limit,changes.size());i++){AdvancedAnalytics.Frame f=changes.get(i);LinearLayout event=card(date(f.round.get("timestamp")));note(event,(f.leaders.size()>1?"Joint leaders: ":"Leader: ")+leaderNames(f.leaders));Integer rank=f.ranks.get(state.player);metric(event,"Your rank",rank==null?"Not entered":"#"+rank,blue);button(event,"View this round",()->host.round(f.round));}more(changes.size());}
    private AdvancedAnalytics.Session findSession(String id){for(AdvancedAnalytics.Session s:report.sessions)if(s.id.equals(id))return s;return null;}
    private void pickSession(boolean second){List<AdvancedAnalytics.Session> choices=new ArrayList<>(report.sessions);String[] names=new String[choices.size()];for(int i=0;i<names.length;i++)names[i]=choices.get(i).name+" · "+choices.get(i).rounds.size()+" rounds";host.choose(second?"Second session":"First session",names,i->{if(second){String previous=state.sessionB;state.sessionB=choices.get(i).id;if(state.sessionB.equals(state.sessionA))state.sessionA=previous;}else{String previous=state.sessionA;state.sessionA=choices.get(i).id;if(state.sessionA.equals(state.sessionB))state.sessionB=previous;}host.changed();});}
    private void sessions(){List<AdvancedAnalytics.Session> groups=report.sessions;if(groups.isEmpty()){cardMessage("No session rounds","No saved rounds belong to a session in this scope.");return;}if(findSession(state.sessionA)==null)state.sessionA=groups.get(0).id;if(findSession(state.sessionB)==null||state.sessionA.equals(state.sessionB)){state.sessionB="";for(AdvancedAnalytics.Session s:groups)if(!s.id.equals(state.sessionA)){state.sessionB=s.id;break;}}
        AdvancedAnalytics.Session first=findSession(state.sessionA),second=findSession(state.sessionB);button(root,"First session · "+first.name,()->pickSession(false));if(second!=null)button(root,"Second session · "+second.name,()->pickSession(true));else cardMessage("One session available","Use All sessions / a wider date range to compare two sessions.");
        for(AdvancedAnalytics.Session session:new AdvancedAnalytics.Session[]{first,second})if(session!=null){LinearLayout c=card(session.name+(session.active?" · Active":""));summary(c,AdvancedAnalytics.stats(state.player,session.rounds));metric(c,"Table rounds",String.valueOf(session.rounds.size()),WHITE);}
        if(second!=null){AdvancedAnalytics.Stats x=AdvancedAnalytics.stats(state.player,first.rounds),y=AdvancedAnalytics.stats(state.player,second.rounds);LinearLayout c=card("Session difference · First minus second");metric(c,"Total points",signed(x.points-y.points),gold);metric(c,"Average points/round",dec(x.average-y.average),blue);note(c,"Averages use this player's own played rounds. The selected date filter may include only part of either session.");}
        cardMessage("Session membership","Rounds belong to their saved session. Older rounds use session start/end times, choosing the latest start if sessions overlap. Unmatched rounds appear as Unassigned.");
    }
    private void impacts(){List<AdvancedAnalytics.Frame> frames=report.impacts();cardMessage("Rounds that moved the table","Sorted by total rank-place movement of existing players, then absolute points changed. New players have no earlier rank; they are marked Entry. Scores and ranks start from this filter's zero baseline.");for(int i=0;i<Math.min(state.limit,frames.size());i++){AdvancedAnalytics.Frame f=frames.get(i);LinearLayout c=card(date(f.round.get("timestamp")));note(c,"Hukum: "+name(AdvancedAnalytics.text(f.round,"hukumId"))+" · Bid "+AdvancedAnalytics.number(f.round.get("bid")));metric(c,"Players moved",String.valueOf(f.moved),WHITE);metric(c,"Rank-place movement",String.valueOf(f.movement),blue);metric(c,"Absolute point changes",String.valueOf(f.swing),gold);metric(c,"Your point change",AdvancedAnalytics.role(f.round,state.player).isEmpty()?"Did not play":signed(AdvancedAnalytics.delta(f.round,state.player)),WHITE);Integer before=f.before.get(state.player),after=f.ranks.get(state.player);metric(c,"Your rank",after==null?"Not entered":(before==null?"Entry":"#"+before)+" → #"+after,blue);button(c,"View round details",()->host.round(f.round));}more(frames.size());}
    private void records(){AdvancedAnalytics.Stats s=report.players.get(state.player);LinearLayout c=card("Personal records");if(s.played==0){note(c,"No played rounds for this player in this scope.");return;}metric(c,"Highest single-round points",signed(s.bestRound),green);metric(c,"Lowest single-round points",signed(s.worstRound),red);metric(c,"Longest winning streak",String.valueOf(s.longestWins),green);metric(c,"Longest losing streak",String.valueOf(s.longestLosses),red);metric(c,"Highest lead margin",String.valueOf(report.highestLead.getOrDefault(state.player,0L)),gold);metric(c,"Largest comeback",String.valueOf(report.comeback.getOrDefault(state.player,0L)),gold);AdvancedAnalytics.Session best=null;long bestScore=Long.MIN_VALUE;for(AdvancedAnalytics.Session session:report.sessions){AdvancedAnalytics.Stats stats=AdvancedAnalytics.stats(state.player,session.rounds);if(stats.played>0&&stats.points>bestScore){best=session;bestScore=stats.points;}}if(best!=null){metric(c,"Best session points",signed(bestScore),gold);note(c,best.name+" · Within the selected date/session scope.");}sample(c,s);}
    private void insights(){windows();LinearLayout c=card("Auto insights · "+name(state.player));for(String insight:report.insights(state.player,state.window)){note(c,"• "+insight);gap(c,8);}note(c,"Calculated on this device from your saved table.");}
    private void chart(LinearLayout parent,List<Map<String,Object>> rounds,String first,String second,String title){if(rounds.isEmpty())return;gap(parent,10);parent.addView(text(title,15,WHITE,true));note(parent,name(first)+(second.isEmpty()?"":" · "+name(second)));TextView detail=text("",13,MUTED,false);List<Long> x=new ArrayList<>(),y=new ArrayList<>();x.add(0L);y.add(0L);long p=0,q=0;for(Map<String,Object> r:rounds){if(!AdvancedAnalytics.role(r,first).isEmpty())p+=AdvancedAnalytics.delta(r,first);if(!second.isEmpty()&&!AdvancedAnalytics.role(r,second).isEmpty())q+=AdvancedAnalytics.delta(r,second);x.add(p);y.add(q);}Trend chart=new Trend(x,second.isEmpty()?Collections.emptyList():y,detail,rounds,first,second);parent.addView(chart,new LinearLayout.LayoutParams(-1,dp(210)));parent.addView(detail);
        LinearLayout controls=new LinearLayout(a);controls.setOrientation(LinearLayout.HORIZONTAL);
        for(int direction:new int[]{-1,1}){LinearLayout cell=new LinearLayout(a);cell.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams size=new LinearLayout.LayoutParams(0,-2,1);if(direction<0)size.rightMargin=dp(8);controls.addView(cell,size);button(cell,direction<0?"Previous chart round":"Next chart round",()->{chart.cursor=Math.max(0,Math.min(chart.first.size()-1,chart.cursor+direction));chart.update();});}parent.addView(controls);
        note(parent,"Gold: "+name(first)+(second.isEmpty()?"":" · Blue: "+name(second))+". Tap the chart or use left/right keys to inspect a round. Scores carry forward on skipped rounds; the filter starts at zero.");}
    private final class Trend extends View {
        final List<Long> first,second;final TextView detail;final List<Map<String,Object>> rounds;final String firstId,secondId;float reveal=1f;final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);int cursor;float downY;
        Trend(List<Long> first,List<Long> second,TextView detail,List<Map<String,Object>> rounds,String firstId,String secondId){super(a);this.first=first;this.second=second;this.detail=detail;this.rounds=rounds;this.firstId=firstId;this.secondId=secondId;cursor=first.size()-1;setFocusable(true);setClickable(true);update();host.draw(this,value->{reveal=value;invalidate();});}
        void update(){String label=cursor==0?"Filter baseline":("Round "+cursor+" · "+date(rounds.get(cursor-1).get("timestamp")));label+=" · "+name(firstId)+" "+signed(first.get(cursor));if(!second.isEmpty())label+=" · "+name(secondId)+" "+signed(second.get(cursor));detail.setText(label);setContentDescription("Score chart. "+label+". Left and right keys inspect rounds.");invalidate();}
        @Override public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()==android.view.MotionEvent.ACTION_DOWN){downY=e.getY();return true;}if(e.getAction()==android.view.MotionEvent.ACTION_UP){if(Math.abs(e.getY()-downY)<dp(20)){cursor=Math.max(0,Math.min(first.size()-1,Math.round((e.getX()-dp(48))/Math.max(1,getWidth()-dp(60))*(first.size()-1))));update();performClick();}return true;}return true;}
        @Override public boolean performClick(){super.performClick();return true;}
        @Override public boolean onKeyDown(int key,android.view.KeyEvent event){if(key==android.view.KeyEvent.KEYCODE_DPAD_LEFT||key==android.view.KeyEvent.KEYCODE_DPAD_RIGHT){cursor=Math.max(0,Math.min(first.size()-1,cursor+(key==android.view.KeyEvent.KEYCODE_DPAD_LEFT?-1:1)));update();return true;}return super.onKeyDown(key,event);}
        @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);long low=Collections.min(first),high=Collections.max(first);if(!second.isEmpty()){low=Math.min(low,Collections.min(second));high=Math.max(high,Collections.max(second));}if(low==high&&low==0){low=-1;high=1;}double range=Math.max(1d,(double)high-low);float left=dp(48),top=dp(22),width=Math.max(1,getWidth()-dp(60)),height=Math.max(1,getHeight()-dp(50));paint.setStrokeWidth(dp(1));paint.setColor(BORDER);float zero=top+(float)(high/range)*height;canvas.drawLine(left,zero,left+width,zero,paint);paint.setColor(MUTED);paint.setTextSize(dp(10));paint.setStyle(Paint.Style.FILL);canvas.drawText(axis(high),0,top,paint);canvas.drawText(axis(low),0,top+height,paint);canvas.save();canvas.clipRect(left-dp(2),top-dp(2),left+width*reveal+dp(2),top+height+dp(2));series(canvas,first,gold,left,top,width,height,high,range);if(!second.isEmpty())series(canvas,second,blue,left,top,width,height,high,range);canvas.restore();paint.setColor(MUTED);paint.setStrokeWidth(dp(1));float x=left+width*cursor/Math.max(1,first.size()-1);canvas.drawLine(x,top,x,top+height,paint);}
        String axis(long value){double abs=Math.abs((double)value);if(abs>=1e12)return String.format(Locale.ROOT,"%.1e",(double)value);if(abs>=1e9)return dec(value/1e9)+"B";if(abs>=1e6)return dec(value/1e6)+"M";if(abs>=1e3)return dec(value/1e3)+"K";return String.valueOf(value);}
        void series(Canvas canvas,List<Long> values,int color,float left,float top,float width,float height,long high,double range){Path path=new Path();for(int i=0;i<values.size();i++){float x=left+width*i/Math.max(1,values.size()-1),y=top+(float)(((double)high-values.get(i))/range)*height;if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}paint.setColor(color);paint.setStrokeWidth(dp(2));paint.setStyle(Paint.Style.STROKE);canvas.drawPath(path,paint);paint.setStyle(Paint.Style.FILL);}
    }
}
